                        <span style={sx("font-family:'Geist Mono', ui-monospace, Menlo, monospace;font-size:.88em;padding:2px 7px;border-radius:7px;background:#0b0c0c;color:#f2f3f1;white-space:nowrap")}>
                          {"@aozibot buy $APPLE 0.25 AAPL"}
                        </span>
